//It Magnifies & Shines by Joshy20XX - December 28, 2024

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv_circle = (fragCoord - .5*iResolution.xy)/iResolution.y; //Circle
    uv_circle.x -= sin(iTime/3.) * .5 ;

    //align uv texture
    vec2 align_uv = (fragCoord/iResolution.xy);
    vec3 col = texture(iChannel0, align_uv).rgb;

    //Draw the circle or any SDF shape with the sharpness of your choice
    float circle = smoothstep(.5, .5, length(uv_circle) * 2.);

    //You can give it a color or not.
    vec3 circle_col = vec3(0.2,0.2,0.2);

    //This is how I roughly make the magnifying effect
    vec3 distort = texture(iChannel0, align_uv *.5-.8).rgb;
    circle_col += distort;

    //Blend the effect based on the distance of the shape and adjust the final color.
    if (circle < .5) col = circle_col;  
    col -= circle / 3.5;

    // And PRESTO!
    fragColor = vec4(col,1.0);
}
